import { Component, inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Location } from '@angular/common';
import { TablerIconComponent, IconArrowLeft, IconCheck, IconEdit } from '@tabler/icons-angular';
import { HrmButton } from 'hrm-ui';
import { PEOPLE } from './_people';
import { SgEmpDetail } from './emp-detail-card';

/** Trang BẢN GHI TOÀN TRANG cho template "Chế độ xem dữ liệu" — đích của mode
 *  Toàn trang (điều hướng) và Tab mới (window.open) từ hrm-detail-peek.
 *  Nhận ?id=, tìm trong PEOPLE (nguồn dữ liệu chung), render thẻ chi tiết dùng chung.
 *  Toàn trang: action bar là TOPNAV full-width sticky (thoát card) — chỉ áp cho mode này. */
@Component({
  selector: 'sg-list-record',
  imports: [TablerIconComponent, HrmButton, SgEmpDetail],
  template: `
    <div class="lr">
      <!-- TOPNAV full-width, STICKY sát đỉnh vùng cuộn: back + tiêu đề (trái) + hành động (phải).
           margin-inline âm để trải hết bề rộng content shell (thoát padding + canh giữa). -->
      <div class="lr-nav">
        <div class="lr-nav-in">
          <div class="lr-nav-l">
            <hrm-button size="sm" [iconOnly]="true" ariaLabel="Quay lại" (click)="back()"><tabler-icon [icon]="icBack" [size]="18" /></hrm-button>
            <h1 class="lr-t">Chi tiết nhân viên</h1>
          </div>
          @if (row) {
            <div class="lr-nav-r">
              <hrm-button variant="primary" size="md"><tabler-icon [icon]="icCheck" [size]="15" /> Duyệt chính thức</hrm-button>
              <hrm-button size="md"><tabler-icon [icon]="icEdit" [size]="15" /> Sửa hồ sơ</hrm-button>
            </div>
          }
        </div>
      </div>

      <!-- Nội dung: card canh giữa, rộng theo page content. -->
      <div class="lr-body">
        @if (row) {
          <div class="lr-card"><sg-emp-detail [emp]="row" [pageMode]="true" /></div>
        } @else {
          <p class="lr-empty">Không tìm thấy bản ghi.</p>
        }
      </div>
    </div>
  `,
  host: { class: 'sg-list-record' },
  styles: [`
    :host { display: block; }
    /* Bỏ padding của vùng cuộn shell KHI trang này hiện → topnav sticky trải sát mép + neo sát đỉnh.
       Nhịp trên/dưới do topnav + body tự lo. */
    ::ng-deep .shell-content:has(sg-list-record) { padding: 0 !important; }
    .lr { display: block; }

    /* TOPNAV: full bề rộng content shell, sticky đỉnh, nền surface + gạch dưới (như top nav). */
    .lr-nav {
      position: sticky; top: 0; z-index: 10;
      background: var(--bg-surface); border-bottom: 1px solid var(--border-sub);
    }
    /* Padding 2 bên = header design system (.lp-head = 16px = --space-4) để đồng bộ. */
    .lr-nav-in {
      max-width: 1080px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between; gap: var(--space-4);
      padding: var(--space-3) var(--space-4);
    }
    .lr-nav-l { display: flex; align-items: center; gap: var(--space-3); min-width: 0; }
    .lr-nav-r { display: flex; align-items: center; gap: var(--space-2); flex: none; }
    /* Tiêu đề đồng bộ header DS (fs-30) nhưng gọn trong topnav. */
    .lr-t { margin: 0; font-size: var(--fs-20); font-weight: 600; color: var(--text-strong); white-space: nowrap; }

    /* Body: card canh giữa, cách topnav 1 nhịp. */
    /* Body cùng padding 2 bên với topnav (space-4) → nội dung thẳng lề tiêu đề header. */
    .lr-body { max-width: 1080px; margin: 0 auto; padding: var(--space-5) var(--space-4) var(--space-2); }
    .lr-card {
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); padding: var(--space-5);
    }
    .lr-empty { color: var(--text-sub); }
  `],
})
export class SgListRecord {
  private readonly location = inject(Location);
  protected readonly icBack = IconArrowLeft;
  protected readonly icCheck = IconCheck;
  protected readonly icEdit = IconEdit;
  /** Bản ghi theo ?id= (snapshot — vào trang là điều hướng mới, component dựng lại). */
  protected readonly row = PEOPLE.find(
    (p) => String(p['id']) === (inject(ActivatedRoute).snapshot.queryParamMap.get('id') ?? ''),
  ) ?? null;

  protected back(): void { this.location.back(); }
}
